def keys(self):
    """
    Return the keys of the record.

    :return: list of key names
    """
    return list(self._keys.keys())

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    if not keys:
        return {key: self[key] for key in self.keys()}
    else:
        result = {}
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self):
                    raise IndexError("Index out of bounds")
                result[self.keys()[key]] = self[key]
            else:
                result[key] = self[key]
        return result

def pop_u16(self):
    """
    Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    return self.unpack('>H', 2)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    # Create a new class with the given name and fields
    class _Point(Point):
        __slots__ = ()
        _fformat = "(%s)" % ", ".join(["%r" if f is None else "%s=%%r" % f for f in fields])

        def __init__(self, *args):
            if len(args) != len(fields):
                raise ValueError("Invalid number of arguments")
            for i, f in enumerate(fields):
                if f is not None:
                    vars()[f] = args[i]

        def __repr__(self):
            return "Point(%s)" % ", ".join([str(getattr(self, f)) for f in fields])

    # Add the srid_map to the class
    _Point._srid_map = srid_map

    return _Point

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """

    def inner(func):
        @functools.wraps(func)
        def new_func(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return new_func
    return inner

def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    retcode = 0
    stdout = b''
    stderr = b''

    try:
        cmd = parse_shebang.normalize_cmd(cmd)
    except parse_shebang.ExecutableNotFoundError as e:
        return e.to_output()

    partitions = partition(cmd, varargs, target_concurrency, _max_length)

    def run_cmd_partition(run_cmd):
        return cmd_output(*run_cmd, encoding=None, retcode=None, **kwargs)

    threads = min(len(partitions), target_concurrency)
    with _thread_mapper(threads) as thread_map:
        results = thread_map(run_cmd_partition, partitions)

        for proc_retcode, proc_out, proc_err in results:
            retcode |= bool(proc_retcode)
            stdout += proc_out
            stderr += proc_err

    return retcode, stdout, stderr

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    return list(seq)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = LRUCache(maxsize, timer=timer, typed=typed)
        def wrapper(*args, **kwargs):
            k = cache.key(*args, **kwargs)
            try:
                return cache[k]
            except KeyError:
                pass  # key not found
            v = func(*args, **kwargs)
            try:
                cache[k] = v
            except ValueError:
                pass  # value too large
            return v
        return _update_wrapper(wrapper, func)
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    from unstdlib.standard.collections_ import RecentlyUsedContainer

    def decorator(fn):
        cache = RecentlyUsedContainer(maxsize=maxsize, typed=typed)

        def wrapper(*args, **kwargs):
            k = cache.key(*args, **kwargs)
            try:
                return cache[k]
            except KeyError:
                pass  # key not found
            v = fn(*args, **kwargs)
            try:
                cache[k] = v
            except ValueError:
                pass  # value too large
            return v

        wrapper.cache = cache
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def _wrapper(f):
        try:
            f = functools.lru_cache(maxsize=maxsize, typed=typed)(f)
        except AttributeError:
            print(
                "LRU caching is not available in Pyton 2.7, "
                "this will have no effect!"
            )
            pass
        return f
    return _wrapper

