def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key, value = self._items.popitem(last=False)
        return (key, value)
    except KeyError:
        raise KeyError("popitem(): dictionary is empty")

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    if key in self:
        return self[key]
    else:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

def directlyProvidedBy(object):
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    return object.__providedBy__()

def patched_normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            patched_normalizeargs(v, output)

    return output

def is_fill_request_seq(seq):
    """
    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequest):
        return True
    elif isinstance(seq, list):
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    return False

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {k: v for k, v in d1.items() if k not in d2 or v != d2[k]}
    else:
        result = {}
        for k, v in d1.items():
            if k not in d2 or v != d2[k]:
                result[k] = v
            elif isinstance(v, dict):
                sub_result = difference(v, d2[k], level - 1)
                if sub_result:
                    result[k] = sub_result
        return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a partial observer schema from a Kubernetes resource manifest.

    Args:
        manifest_dict (dict): Partial Kubernetes resource manifest
        first_level (bool, optional): If True, indicates that the dictionary represents the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer schema

    This function creates a new dictionary from the manifest dictionary and replaces all non-list and non-dict values by None.

    In case of first-level dictionary (i.e. complete observer schema for a resource), the values of the identifying fields are copied from the manifest file.
    """
    new_dict = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            new_dict[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            new_dict[key] = [generate_default_observer_schema_dict(item, first_level=False) for item in value]
        else:
            new_dict[key] = None

    if first_level:
        for key in ["apiVersion", "kind", "metadata"]:
            new_dict[key] = manifest_dict[key]

    return new_dict

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """
    Together with :func:`update_last_applied_manifest_dict_from_resp`, this function is called recursively to update a partial ``last_applied_manifest`` from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in ``last_applied_manifest`` if they are not yet present
    """
    for i, field in enumerate(observer_schema):
        if field["name"] not in last_applied_manifest:
            last_applied_manifest[field["name"]] = None
        if field["type"] == "list":
            if field["name"] not in response:
                continue
            if len(response[field["name"]]) != len(last_applied_manifest[field["name"]]):
                last_applied_manifest[field["name"]] = response[field["name"]]
            else:
                update_last_applied_manifest_list_from_resp(last_applied_manifest[field["name"]], field["items"], response[field["name"]])
        elif field["type"] == "dict":
            if field["name"] not in response:
                continue
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field["name"]], field["properties"], response[field["name"]])
        else:
            if field["name"] not in response:
                continue
            last_applied_manifest[field["name"]] = response[field["name"]]

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field in observer_schema:
        if field not in response:
            raise KeyError(f"Observed field {field} is not present in the Kubernetes response")
        if isinstance(observer_schema[field], dict):
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        else:
            last_applied_manifest[field] = response[field]

def formatmany(self, sql, many_params):
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes

    :param many_params: A list of in-style parameters.
    :type many_params: Iterable[Union[Mapping, Sequence]]

    :return: A tuple containing the formatted SQL query and a list of converted out-style parameters.
    :rtype: Tuple[str or bytes, List[Dict or List]]
    """
    # Check if the SQL query is a string or bytes
    if not isinstance(sql, (str, bytes)):
        raise ValueError("The SQL query must be a string or bytes")

    # Check if the many_params is an iterable
    if not isinstance(many_params, Iterable):
        raise ValueError("The many_params must be an iterable")

    # Check if the many_params is a list of mappings or sequences
    if not all(isinstance(params, (Mapping, Sequence)) for params in many_params):
        raise ValueError("The many_params must be a list of mappings or sequences")

    # Check if the SQL query is a string
    if isinstance(sql, str):
        # Check if the SQL query contains in-style parameters
        if re.search(r"{(\d+)}", sql):
            # Replace the in-style parameters with out-style parameters
            sql = re.sub(r"{(\d+)}", r"?", sql)

            # Create a list of out-style parameters
            out_params = [{} for _ in many_params]

            # Add the out-style parameters to the list
            for i, params in enumerate(many_params):
                if isinstance(params, Mapping):
                    for key, value in params.items():
                        out_params[i][key] = value
                else:
                    for j, value in enumerate(params):
                        out_params[i][j] = value

            return sql, out_params
        else:
            return sql, []
    else:
        # Check if the SQL query contains in-style parameters
        if re.search(b"{(\d+)}", sql):
            # Replace the in-style parameters with out-style parameters
            sql = re.sub(b"{(\d+)}", b"?", sql)

            # Create a list of out-style parameters
            out_params = [{} for _ in many_params]

            # Add the out-style parameters to the list
            for i, params in enumerate(many_params):
                if isinstance(params, Mapping):
                    for key, value in params.items():
                        out_params[i][key] = value
                else:
                    for j, value in enumerate(params):
                        out_params[i][j] = value

            return sql, out_params
        else:
            return sql, []

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        raise ValueError("path cannot be empty")

    if not os.path.exists(path):
        raise ValueError("path does not exist")

    if not os.path.isdir(path):
        raise ValueError("path is not a directory")

    # Check for required files and directories
    required_files = ["inventory.json", "root.json"]
    required_dirs = ["ocfl_object"]

    for file in required_files:
        if not os.path.exists(os.path.join(path, file)):
            raise ValueError(f"Required file {file} does not exist")

    for dir in required_dirs:
        if not os.path.exists(os.path.join(path, dir)):
            raise ValueError(f"Required directory {dir} does not exist")

    # Check for valid JSON files
    for file in required_files:
        with open(os.path.join(path, file), "r") as f:
            try:
                json.load(f)
            except json.JSONDecodeError as e:
                raise ValueError(f"Invalid JSON in {file}: {e}")

    # Check for valid inventory.json
    inventory_path = os.path.join(path, "inventory.json")
    with open(inventory_path, "r") as f:
        inventory = json.load(f)

    if "version" not in inventory:
        raise ValueError("Inventory does not have a version")

    if "head" not in inventory:
        raise ValueError("Inventory does not have a head")

    if "digestAlgorithm" not in inventory:
        raise ValueError("Inventory does not have a digestAlgorithm")

    if "digest" not in inventory:
        raise ValueError("Inventory does not have a digest")

    # Check for valid root.json
    root_path = os.path.join(path, "root.json")
    with open(root_path, "r") as f:
        root = json.load(f)

    if "id" not in root:
        raise ValueError("Root does not have an id")

    if "type" not in root:
        raise ValueError("Root does not have a type")

    if "digestAlgorithm" not in root:
        raise ValueError("Root does not have a digestAlgorithm")

    if "digest" not in root:
        raise ValueError("Root does not have a digest")

    # Check for valid ocfl_object directory
    ocfl_object_path = os.path.join(path, "ocfl_object")
    if not os.path.exists(ocfl_object_path):
        raise ValueError("ocfl_object directory does not exist")

    if not os.path.isdir(ocfl_object_path):
        raise ValueError("ocfl_object is not a directory")

    # Check for valid version directory
    version_path = os.path.join(ocfl_object_path, inventory["head"])
    if not os.path.exists(version_path):
        raise ValueError("Version directory does not exist")

    if not os.path.isdir(version_path):
        raise ValueError("Version is not a directory")

    # Check for valid content directory
    content_path = os.path.join(version_path, "content")
    if not os.path.exists(content_path):
        raise ValueError("Content directory does not exist")

    if not os.path.isdir(content_path):
        raise ValueError("Content is not a directory")

    # Check for valid version.json
    version_json_path = os.path.join(version_path, "version.json")
    if not os.path.exists(version_json_path):
        raise ValueError("Version.json does not exist")

    if not os.path.isfile(version_json_path):
        raise ValueError("Version.json is not a file")

    with open(version_json_path, "r") as f:
        version_json = json.load(f)

    if "id" not in version_json:
        raise ValueError("Version.json does not have an id")

    if "type" not in version_json:
        raise ValueError("Version.json does not have a type")

    if "digestAlgorithm" not in version_json:
        raise ValueError("Version.json does not have a digestAlgorithm")

    if "digest" not in version_json:
        raise ValueError("Version.json does not have a digest")

    # Check for valid content.json
    content_json_path = os.path.join(content_path, "content.json")
    if not os.path.exists(content_json_path):
        raise ValueError("Content.json does not exist")

    if not os.path.isfile(content_json_path):
        raise ValueError("Content.json is not a file")

    with open(content_json_path, "r") as f:
        content_json = json.load(f)

    if "id" not in content_json:
        raise ValueError("Content.json does not have an id")

    if "type" not in content_json:
        raise ValueError("Content.json does not have a type")

    if "digestAlgorithm" not in content_json:
        raise ValueError("Content.json does not have a digestAlgorithm")

    if "digest" not in content_json:
        raise ValueError("Content.json does not have a digest")

    # Check for valid content directory
    for file in content_json["files"]:
        file_path = os.path.join(content_path, file)
        if not os.path.exists(file_path):
            raise ValueError(f"File {file} does not exist")

        if not os.path.isfile(file_path):
            raise ValueError(f"File {file} is not a file")

    # Check for valid version.json
    for file in version_json["files"]:
        file_path = os.path.join(version_path, file)
        if not os.path.exists(file_path):
            raise ValueError(f"File {file} does not exist")

        if not os.path.isfile(file_path):
            raise ValueError(f"File {file} is not a file")

    # Check for valid inventory.json
    for file in inventory["files"]:
        file_path = os.path.join(path, file)
        if not os.path.exists(file_path):
            raise ValueError(f"File {file} does not exist")

        if not os.path.isfile(file_path):
            raise ValueError(f"File {file} is not a file")

    # Check for valid root.json
    for file in root["files"]:
        file_path = os.path.join(path, file)
        if not os.path.exists(file_path):
            raise ValueError(f"File {file} does not exist")

        if not os.path.isfile(file_path):
            raise ValueError(f"File {file} is not a file")

    return True

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    status_str = ''
    for entry in self.entries:
        status_str += prefix + str(entry['response']['status']) + '\n'
    return status_str

def is_valid(self, identifier):
    """Return True if identifier is valid, always True in this base implementation."""
    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        # Check if the type value is present and valid
        if 'type' in inventory and inventory['type'] in self.spec_versions:
            spec_version = inventory['type']
        else:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version

    # Check the version of the inventory against the supported versions
    if spec_version not in self.spec_versions:
        raise ValueError(f"Unsupported inventory version: {spec_version}")

    # Check the inventory against the schema
    try:
        self.schema.validate(inventory)
    except ValidationError as e:
        raise ValueError(f"Invalid inventory: {e}")

    # Check the inventory against the specification
    if spec_version == '1.0':
        # Check the inventory against the 1.0 specification
        pass
    elif spec_version == '2.0':
        # Check the inventory against the 2.0 specification
        pass
    else:
        raise ValueError(f"Unsupported inventory version: {spec_version}")

    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    :param manifest_files: List of files in the manifest
    :param digests_used: List of digests used in the manifest
    """
    # Check if all digests in the manifest are present
    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError(f"Digest {digest} is not present in the manifest")

    # Check if all digests used in the manifest are actually used
    for file in manifest_files:
        if file["digest"] not in digests_used:
            raise ValueError(f"Digest {file['digest']} is not used in the manifest")

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("prior must be an InventoryValidator object")

    if self.version != prior.version:
        raise ValueError("prior version must match current inventory version")

    if self.parameters != prior.parameters:
        raise ValueError("prior parameters must match current inventory parameters")

