def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for content_file in inventory.get_content_files(version):
        logical_path = content_file.get_logical_path()
        if logical_path in logical_path_map:
            logical_path_map[logical_path].add(content_file)
        else:
            logical_path_map[logical_path] = {content_file}
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    for file_path, file_info in fixity.items():
        if file_path not in manifest_files:
            raise ValueError(f"File {file_path} is not listed in the manifest")

        if not isinstance(file_info, dict):
            raise ValueError(f"Fixity information for {file_path} must be a dictionary")

        for field, value in file_info.items():
            if field not in ("md5", "sha256"):
                raise ValueError(f"Invalid field {field} in fixity information for {file_path}")

            if not isinstance(value, str):
                raise ValueError(f"Fixity value for {file_path} must be a string")

            if not value.isalnum():
                raise ValueError(f"Fixity value for {file_path} must be alphanumeric")

    return True

