    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

def unquote(name):
    """Remove quote from the given name."""
    if re.match(r'"', name):
        return name[1:-1]
    else:
        return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1

    if platform == 1:
        # POSIX
        return re.split(r'(\s+)', s)
    else:
        # Windows/CMD
        return re.split(r'(\s+|"(?:\\.|[^"])*")', s)

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    m = re.match(r'^(\d+)\s*(\w+)$', frequency)
    if not m:
        raise ValueError("Invalid frequency string")
    num = int(m.group(1))
    unit = m.group(2)
    if unit == "week":
        return datetime.timedelta(weeks=num)
    elif unit == "day":
        return datetime.timedelta(days=num)
    elif unit == "hour":
        return datetime.timedelta(hours=num)
    elif unit == "minute":
        return datetime.timedelta(minutes=num)
    elif unit == "second":
        return datetime.timedelta(seconds=num)
    else:
        raise ValueError("Invalid frequency unit")

def is_local(host):
    try:
        return socket.gethostbyname(host) == "127.0.0.1"
    except socket.gaierror:
        return False

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if isinstance(pattern, str):
        return re.compile(pattern)
    elif isinstance(pattern, re._pattern_type):
        return pattern
    else:
        raise TypeError("Invalid pattern type: %r" % (pattern,))

    if strip:
        return pattern.strip()
    else:
        return pattern

def dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if compatibility.PY2:
        return yaml.dump(obj, encoding='utf-8', Dumper=dumper)
    else:
        return yaml.dump(obj, Dumper=dumper)

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    return np.exp(-((x - 0.2) ** 2) / (2 * 0.1 ** 2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename) as f:
                config = yaml.safe_load(f)
        except yaml.YAMLError as e:
            errors.append(e)
            continue

        if overrides:
            config.update(overrides)

        if resolve_env:
            config = resolve_env_vars(config)

        configs[config_filename] = config

    return configs, errors

def resolve_env_vars(config):
    """
    Recursively resolve environment variables in a configuration dictionary.
    """
    for key, value in config.items():
        if isinstance(value, str) and value.startswith('$'):
            config[key] = os.environ[value[1:]]
        elif isinstance(value, dict):
            config[key] = resolve_env_vars(value)

    return config

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    else:
        return obj

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        return (seq, str)
    elif isinstance(seq, bytes):
        return (seq, bytes)
    elif isinstance(seq, bytearray):
        return (seq, bytearray)
    elif isinstance(seq, memoryview):
        return (seq, memoryview)
    elif isinstance(seq, array.array):
        return (seq, array.array)
    elif isinstance(seq, collections.abc.Sequence):
        return (seq, collections.abc.Sequence)
    elif isinstance(seq, collections.abc.Iterable):
        return (seq, collections.abc.Iterable)
    else:
        raise TypeError("Expected a sequence type, but got %s" % type(seq))

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if tentative:
        # If the candidate is tentative, we only need to check that it
        # has the necessary methods and attributes, without actually
        # calling them.
        for method in iface.methods:
            if not hasattr(candidate, method.name):
                return False
        for attribute in iface.attributes:
            if not hasattr(candidate, attribute.name):
                return False
        return True
    else:
        # If the candidate is not tentative, we need to actually call
        # the methods and check that they return the correct values.
        for method in iface.methods:
            if not method.verify(candidate):
                return False
        for attribute in iface.attributes:
            if not attribute.verify(candidate):
                return False
        return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__

    :param bases: A tuple of base classes
    :param explicit_mc: An explicit metaclass
    :return: The metaclass to use for the class
    """
    if explicit_mc is not None:
        return explicit_mc
    else:
        for base in bases:
            if isinstance(base, type) and issubclass(base, type):
                return base
        return type

def pop(self, key, default=None):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not None:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap,
                self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        node = self._head[2]
        if node is self._tail:
            raise KeyError('list is empty')
        self._find_lt(node[0])
        self._remove(node)
        return (node[0], node[1])
    except KeyError, e:
        raise BadRequestKeyError(str(e))

def popitem(self):
    """Remove and return the (key, value) pair least recently used.

    This method raises a `KeyError` if the list is empty.
    """
    node = self._head[2]
    if node is self._tail:
        raise KeyError('list is empty')
    self._find_lt(node[0])
    self._remove(node)
    return (node[0], node[1])

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used.

    This method raises a `KeyError` if the dict is empty.
    """
    try:
        key, value = next(reversed(self.items()))
        del self[key]
        return key, value
    except StopIteration:
        raise KeyError("dict is empty")

def popitem(self):
    """Remove and return a random (key, value) pair."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    return re.compile(r"(?:^|,)\s*([^,]+?)\s*(?=$|,)", re.UNICODE | re.MULTILINE)

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    return _converting._Converter()

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    if request.META.get('CONTENT_TYPE', None) == 'application/json':
        return True
    else:
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    new_text = ''
    in_code_block = False
    for line in text.splitlines():
        if not in_code_block:
            for tag in line.split():
                if tag.startswith('#'):
                    tags.add(tag[1:])
                    if replacer is not None:
                        new_text += replacer(tag[1:]) + ' '
                    else:
                        new_text += tag + ' '
        else:
            new_text += line + '\n'
        if line.startswith('```'):
            in_code_block = not in_code_block
    return tags, new_text

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.

    :param url: The URL of the remote resource.
    :return: The content type of the remote resource, or None if the content type could not be determined.
    """

    try:
        response = requests.head(url)
        if response.status_code == 200:
            return response.headers.get('content-type')
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def xml_children_as_dict(node):
    """
    Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children = node.getchildren()
    result = {}
    for child in children:
        tag = child.tag
        if tag not in result:
            result[tag] = []
        result[tag].append(child.text)
    return result

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    logger.debug("send_document: url=%s, data=%s, timeout=%s, method=%s", url, data, timeout, method)
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    if "headers" in kwargs:
        # Update from kwargs
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data, "timeout": timeout, "headers": headers
    })
    try:
        response = requests.request(method, url, *args, **kwargs)
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex

def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new IniType complex type

    :param settings_dirs: list of directories to search for settings files
    :param spec_option: spec option to use when creating the IniType
    :return: list of file names
    """

    file_names = []

    for settings_dir in settings_dirs:
        for root, dirs, files in os.walk(settings_dir):
            for file in files:
                if file.endswith(".ini"):
                    file_names.append(os.path.join(root, file))

    return file_names

def plugins_manager(cls):
    """Gets the plugin manager. """
    return cls._plugin_manager

def validate_from_content(spec_content):
    """
    Validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    # Load the spec content into a dictionary
    spec_data = yaml.load(spec_content, Loader=yaml.FullLoader)

    # Check if the spec data has all required fields
    for field in cls.REQUIRED_FIELDS:
        if field not in spec_data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in spec file")

    # Check if the spec data has all required fields with the correct types
    for field, field_type in cls.REQUIRED_FIELDS_TYPES.items():
        if field not in spec_data or not isinstance(spec_data[field], field_type):
            raise IRValidatorException(f"Field '{field}' in spec file has incorrect type, expected {field_type}")

    # Check if the spec data has all required fields with the correct values
    for field, field_values in cls.REQUIRED_FIELDS_VALUES.items():
        if field not in spec_data or spec_data[field] not in field_values:
            raise IRValidatorException(f"Field '{field}' in spec file has incorrect value, expected one of {field_values}")

    return spec_data

def validate_from_file(yaml_file):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    with open(yaml_file, 'r') as f:
        data = yaml.load(f)

    # validate that all mandatory fields are present
    for field in cls.mandatory_fields:
        if field not in data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in file '{yaml_file}'")

    # validate that all fields have the correct type
    for field, field_type in cls.field_types.items():
        if field not in data:
            continue
        if not isinstance(data[field], field_type):
            raise IRValidatorException(f"Field '{field}' in file '{yaml_file}' has incorrect type. Expected: {field_type}, Actual: {type(data[field])}")

    return data

def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.

    :param dict parser_dict:
    """
    for key, value in parser_dict.items():
        if isinstance(value, dict):
            self._include_groups(value)
        elif key == 'include':
            include_dict = value
            for include_key, include_value in include_dict.items():
                if include_key in parser_dict:
                    raise ValueError('Duplicate key in include dict: %s' % include_key)
                parser_dict[include_key] = include_value

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary of default values for the arguments.
    """
    defaults = {}
    for arg in self.args:
        # If the argument has a default value set in the spec, use it
        if arg.name in self.spec and self.spec[arg.name] is not None:
            defaults[arg.name] = self.spec[arg.name]
        # If the argument has a default value set in the default spec, use it
        elif arg.name in self._default_spec and self._default_spec[arg.name] is not None:
            defaults[arg.name] = self._default_spec[arg.name]
        # If the argument has a default value set in the argument itself, use it
        elif arg.default is not None:
            defaults[arg.name] = arg.default
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """

    deprecated_args = {
        "old_arg1": "new_arg1",
        "old_arg2": "new_arg2",
        "old_arg3": "new_arg3",
    }

    return deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Check if any of the arguments in the answer file are deprecated
    for arg in answer_file_args:
        if arg in self.deprecated_args:
            print(f"WARNING: Argument '{arg}' is deprecated and will be removed in a future version. Please use '{self.deprecated_args[arg]}' instead.")

    # Check if any of the arguments in the cli are deprecated
    for arg in cli_args:
        if arg in self.deprecated_args:
            print(f"WARNING: Argument '{arg}' is deprecated and will be removed in a future version. Please use '{self.deprecated_args[arg]}' instead.")

    # Check if any of the arguments in the answer file or cli are not recognized
    for arg in cli_args:
        if arg not in self.valid_args:
            print(f"WARNING: Argument '{arg}' is not recognized. Please use a valid argument.")

    for arg in answer_file_args:
        if arg not in self.valid_args:
            print(f"WARNING: Argument '{arg}' is not recognized. Please use a valid argument.")

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    for arg in self.args:
        if arg.required and arg.name not in args:
            raise ValueError(f"Missing required argument: {arg.name}")

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"Argument {arg} is longer than {self.length}")

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choices:
            if arg_value not in self.choices[arg_name]:
                raise ValueError(f"Invalid value for argument {arg_name}: {arg_value}. Must be one of {self.choices[arg_name]}")
        else:
            raise ValueError(f"Invalid argument: {arg_name}. Must be one of {self.choices.keys()}")

def validate_min_max_args(args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg < 0 or arg > 100:
            raise ValueError("Argument value must be between 0 and 100")
    return args

def get_nested_custom_and_control_args(args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--'):
            if arg in CONTROL_ARGS:
                control_args[arg] = args[arg]
            elif arg in NESTED_ARGS:
                nested_args[arg] = args[arg]
            else:
                custom_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    else:
        for var in extra_vars:
            if var not in vars_dict:
                vars_dict[var] = None
        return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    with open(os.path.join(plugin_dir, "plugin.json")) as f:
        plugin_spec = json.load(f)
    return {key: value for key, value in plugin_spec.items()}

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = self.config_path
